newBlockTasks.scopedCss:
.forge-contact img { max-width: 100%; display: block; }

.forge-contact .container { max-width: var(--max-width); margin-inline: auto; padding-inline: clamp(20px, 5vw, 64px); }

.forge-contact { padding-block: var(--section-padding); }

.forge-contact .act-dark .section { padding-block: var(--section-padding); }

.forge-contact { text-align: center; border-bottom: 1px solid rgba(255,255,255,0.12); }

.forge-contact .contact__icon { width: 56px; height: 56px; margin: 0 auto 28px; border-radius: 50%; overflow: hidden; }

.forge-contact .contact__icon img { width: 100%; height: 100%; object-fit: contain; }

.forge-contact h2 { font-family: var(--heading-font-family); font-weight: 900; font-size: var(--heading-xl); letter-spacing: -0.02em; line-height: 1.0; color: var(--s2a-color-gray-25, #fff); }

.forge-contact .contact__inquiries { margin: 20px auto 0; max-width: 46ch; font-size: 17px; line-height: 1.5; color: var(--color-on-ink-72); }

.forge-contact .contact__inquiries a { color: #6a8bfc; }

.forge-contact .contact__inquiries a:hover { color: #9db3fd; }

.forge-contact .routes { display: flex; justify-content: center; gap: 48px; flex-wrap: wrap; margin-top: 40px; }

.forge-contact .route { display: flex; flex-direction: column; align-items: center; gap: 12px; text-decoration: none; color: var(--s2a-color-gray-25, #fff); font-weight: 700; font-size: 15px; }

.forge-contact .route__icon { width: 40px; height: 40px; }

.forge-contact .route__icon img { width: 100%; height: 100%; object-fit: contain; filter: invert(1) brightness(2); }

.forge-contact .route span { border-bottom: 1px solid rgba(255,255,255,0.4); padding-bottom: 2px; }

.forge-contact .route:hover span { border-color: var(--s2a-color-gray-25, #fff); }

@media (max-width: 640px) {
.forge-contact .routes { gap: 28px; }
.forge-contact h2 { font-size: 34px; }
}

newBlockTasks.pageGlobalsCss:
:root {
    --heading-font-family: 'adobe-clean-display','Adobe Clean Display','Adobe Clean',-apple-system,'Helvetica Neue',Arial,sans-serif;
    --body-font-family:    'adobe-clean','Adobe Clean',-apple-system,'Helvetica Neue',Arial,sans-serif;

    --heading-xxl: clamp(40px, 6.25vw, 80px);
    --heading-xl:  clamp(32px, 3.6vw, 56px);
    --heading-lg:  40px;
    --heading-md:  24px;
    --body:        20px;
    --body-sm:     16px;

    --line-height-heading: 0.98;
    --line-height-body:    1.45;

    /* paper */        --color-bg:      #ffffff;
    /* ink */          --color-fg:      #000000;
    /* adobe-blue */   --color-accent:  #3b63fb;
    /* blue-deep */    --color-accent-hover: #274dea;
    /* warm-stone */   --color-surface: #eceae7;
    /* cloud */        --color-surface-subtle: #f8f8f8;
    /* gray-700 */     --color-text-subtle: #505050;
    --color-text-secondary: rgba(0,0,0,0.64);
    --color-ink:     #000000;
    --color-on-ink:  #ffffff;
    --color-on-ink-72: rgba(255,255,255,0.72);
    /* adobe-red — RESERVED to the wordmark */ --color-adobe-red: #eb1000;

    --spacing-xs:  4px;
    --spacing-sm:  8px;
    --spacing-md:  16px;
    --spacing-lg:  24px;
    --spacing-xl:  48px;
    --spacing-2xl: 96px;

    --section-padding: 96px;
    --max-width:       1280px;
    --radius:          16px;
    --radius-sm:       12px;
    --radius-pill:     999px;

    --ease: cubic-bezier(0.42, 0, 0, 1);
    --dur:  200ms;
  }

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; hanging-punctuation: first; }

body {
    margin: 0;
    font-family: var(--body-font-family);
    font-size: var(--body-sm);
    line-height: var(--line-height-body);
    color: var(--color-fg);
    background: var(--color-bg);
    -webkit-font-smoothing: antialiased;
  }
